import heapq
V=["A","B","C"]; E=[("A","B",2),("A","C",3),("C","B",-2)]
def dijkstra(s):
    d={v:float("inf") for v in V}; d[s]=0; done=set(); pq=[(0,s)]
    while pq:
        du,u=heapq.heappop(pq)
        if u in done: continue
        done.add(u)                      # 확정: 다시 갱신하지 않는다
        for a,b,w in E:
            if a==u and b not in done and du+w<d[b]:
                d[b]=du+w; heapq.heappush(pq,(d[b],b))
    return d
def bellman(s):
    d={v:float("inf") for v in V}; d[s]=0
    for _ in range(len(V)-1):
        for a,b,w in E:
            if d[a]+w<d[b]: d[b]=d[a]+w
    return d
