import itertools
def ok_set(s):
    s=sorted(s); return all(s[i][1]<=s[i+1][0] for i in range(len(s)-1))
def brute(acts):
    for k in range(len(acts),0,-1):
        for c in itertools.combinations(acts,k):
            if ok_set(c): return k
    return 0
def greedy(acts,key):
    sel=[]
    for a in sorted(acts,key=key):
        if all(a[1]<=b[0] or b[1]<=a[0] for b in sel): sel.append(a)
    return len(sel)
